use std::path::PathBuf;
use std::process::{Command, ExitCode};

fn main() -> ExitCode {
    let manifest_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let package_root = manifest_root.parent().unwrap_or(&manifest_root);
    let node = env::var_os("JSCODESHIFT_NODE").unwrap_or_else(|| "node".into());

    let status = Command::new(node)
        .current_dir(package_root)
        .arg(package_root.join("bin/jscodeshift.js"))
        .args(env::args_os().skip(1))
        .status();

    match status {
        Ok(status) => ExitCode::from(status.code().unwrap_or(1) as u8),
        Err(error) => {
            eprintln!("jscodeshift: unable to start JavaScript compatibility bridge: {error}");
            ExitCode::from(1)
        }
    }
}
